func classifyEvidenceCodeGroup(analysis apiActionAnalysisResponse, evidence apiEvidenceCodeSnippet) string {
	if evidence.Scope == "global" {
		return "global_matches"
	}
	if analysis.Object == nil || evidence.Module == nil {
		return "other"
	}
	objectPrefix := analysis.Object.FullName + "."
	module := *evidence.Module
	if strings.HasPrefix(module, objectPrefix+"Form.") {
		return "form_modules"
	}
	if strings.HasPrefix(module, objectPrefix) {
		return "object_modules"
	}
	if stringInSlice(module, analysis.TraceModules) {
		return "traced_modules"
	}
	return "other"
}

